    // tile carries it, the same level read back from the tile itself: SKSH_u_ds − above_last_start_mm (one frame)
    const refU = isNum(at("ref_u_mm")) ? at("ref_u_mm") : isNum(at("SKSH_u_clean")) && isNum(at("above_last_start_mm")) ? at("SKSH_u_clean") - at("above_last_start_mm") : null;
