      ref_abs: isNum(refU) ? uAbs(M, refU, G) : null,                             // v0.8; NaN when stale
      _stale: rs, _days: at("days_since_fall"), _longest: at("_longest_before"), _derived: G ? G.derived || [] : [],
      _why: gap === 1 ? "no GNSS that day" : ri ? "this day's GNSS is a straight line in the source file (interpolated, not measured)" : null,
